      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "List of job requirements not found or missing in the candidate's CV."
    },
    "concerns": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Any red flags, weaknesses, or concerns noted in the candidate's profile."
    },
    "interview_questions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Suggested technical or behavioral questions to ask the candidate during the interview."
    }
  },
  "required": [
    "score",
    "recommendation",
    "matched_requirements",
    "missing_requirements",
    "concerns",
    "interview_questions"
  ]
}
